<script setup lang="ts">
import {ref} from 'vue';import Modal from './Modal.vue';import ValidationHint from './ValidationHint.vue';import {busy,dispatch,ui} from '../store';
const error=ref('');async function save(){const draft=ui.resourceDraft;if(!draft)return;if(!draft.target.trim()){error.value='先填写网页地址';return}try{await dispatch('resources',draft.mode==='attach'?'attach':'relocate',draft.mode==='attach'?{owner:draft.owner,kind:draft.kind,target:draft.target,title:draft.title||null}:{owner:draft.owner,resourceId:draft.id,target:draft.target});ui.resourceDraft=null}catch(cause){error.value=String((cause as Error).message)}}
</script>
<template><Modal v-if="ui.resourceDraft" :title="ui.resourceDraft.mode==='attach'?'关联网页':'修改地址'" @close="ui.resourceDraft=null"><form novalidate @submit.prevent="save"><div class="editor-body"><div class="field-wrap"><input v-model="ui.resourceDraft.target" aria-label="网页地址" placeholder="https://…" autofocus @input="error=''"/><ValidationHint :message="error" @dismiss="error=''"/></div><input v-if="ui.resourceDraft.mode==='attach'" v-model="ui.resourceDraft.title" aria-label="资料名称" placeholder="名称（可选）" maxlength="200"/></div><footer class="editor-buttons"><button type="button" @click="ui.resourceDraft=null">取消</button><button class="primary" :disabled="!!busy">保存</button></footer></form></Modal></template>
